package org.apache.commons.lang3;

import java.io.*;
import java.io.UnsupportedEncodingException;
import java.lang.reflect.InvocationTargetException;
import java.lang.reflect.Method;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Iterator;
import java.util.List;
import java.util.Locale;
import java.util.regex.Pattern;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for StringUtils.equals(CharSequence, CharSequence)
 * Designed to maximize branch and line coverage.
 */
public class StringUtils_equals_TriageGen1Test {

    @Test
    public void testEquals_SameInstance_ReturnsTrue() {
        String str = "test";
        // Covers: if (cs1 == cs2) return true;
        assertTrue(StringUtils.equals(str, str));
        assertTrue(StringUtils.equals(null, null));
    }

    @Test
    public void testEquals_OneNull_ReturnsFalse() {
        String str = "test";
        // Covers: if (cs1 == null || cs2 == null) return false;
        assertFalse(StringUtils.equals(null, str));
        assertFalse(StringUtils.equals(str, null));
    }

    @Test
    public void testEquals_DifferentStrings_ReturnsFalse() {
        String str1 = "abc";
        String str2 = "def";
        // Covers: return cs1.equals(cs2); (False case)
        assertFalse(StringUtils.equals(str1, str2));
    }

    @Test
    public void testEquals_SameContentDifferentInstances_ReturnsTrue() {
        String str1 = "abc";
        String str2 = new String("abc");
        // Covers: return cs1.equals(cs2); (True case)
        assertTrue(StringUtils.equals(str1, str2));
    }

    @Test
    public void testEquals_StringBuilderAndString_ReturnsTrue() {
        // Testing CharSequence polymorphism
        CharSequence cs1 = "abc";
        CharSequence cs2 = new StringBuilder("abc");
        assertTrue(StringUtils.equals(cs1, cs2));
    }

    @Test
    public void testEquals_EmptyStrings_ReturnsTrue() {
        assertTrue(StringUtils.equals("", ""));
        assertTrue(StringUtils.equals("", new StringBuilder()));
    }
}
